type BRepGraphInc_Storage_WireCoEdgeOrderStatus = typeof BRepGraphInc_Storage_WireCoEdgeOrderStatus[keyof typeof BRepGraphInc_Storage_WireCoEdgeOrderStatus];

/**
 * Result of wire coedge order canonicalization.
 */
declare const BRepGraphInc_Storage_WireCoEdgeOrderStatus: {
  /**
   * Stored order was already connected.
   */
  readonly Connected: 'Connected';
  /**
   * Stored coedges were reordered into an exactly connected chain.
   */
  readonly Reordered: 'Reordered';
  /**
   * Stored coedges were ordered using tolerance-equivalent endpoints.
   */
  readonly ToleranceOrdered: 'ToleranceOrdered';
  /**
   * Stored coedges were grouped into best-effort connected runs.
   */
  readonly Partial: 'Partial';
  /**
   * Wire or coedge ownership/input data is invalid.
   */
  readonly InvalidInput: 'InvalidInput';
};

